  ('20000000-0000-4000-8000-000000000092', 'goseong-attraction-092', '국도 7호선 종점', '기념명소', '고성군의 기념명소 매력을 직접 살펴볼 수 있는 여행 명소 국도 7호선 종점입니다.', '강원특별자치도 고성군 일원', 38.550804, 128.404089, null, null, null, null, 'https://www.gangwon.to/page/gwtour2022/images/map/tourmap_17.pdf', 'https://map.naver.com/p/search/%EA%B5%AD%EB%8F%84%207%ED%98%B8%EC%84%A0%20%EC%A2%85%EC%A0%90', true, null, '{}', null, null, null, null, null, null, null, null, 'open', null, null, null),
  ('20000000-0000-4000-8000-000000000081', 'hwaamsa', '금강산 화암사', '사찰', '수바위 아래 금강산 남쪽 끝자락의 고찰', '강원특별자치도 고성군 토성면 화암사길 100', 38.227037, 128.470185, '/places/hwaamsa.webp', '사진: 고성군 관광포털', 'https://www.gwgs.go.kr/prog/tursmCn/tour/sub02_05/view.do?cntno=57', '큰 바위 수바위를 등지고 선 화암사 전각', 'https://hwaamsa.com/', 'https://map.naver.com/p/search/%EA%B8%88%EA%B0%95%EC%82%B0%20%ED%99%94%EC%95%94%EC%82%AC', true, 'nature', array['free'], '금강산 줄기가 시작되는 신선봉 아래에 자리한 절로, 신라 혜공왕 때 진표율사가 세웠다고 전해요. 절 바로 앞에 왕관처럼 솟은 큰 바위 수바위가 있고, 템플스테이도 운영해요. 수바위를 지나 성인대(신선대)로 오르는 산길이 이어져 울산바위를 바라보는 산행과 묶어 찾기 좋아요.', null, null, '무료', '033-633-1525', '사찰 제1·제2주차장 이용', null, null, 'open', null, null, '2026-11-21'),
  ('20000000-0000-4000-8000-000000000078', 'hwajinpo-kim-il-sung-villa', '김일성별장', '역사관', '화진포 바다를 내려다보는 언덕 위 돌집 별장', '강원특별자치도 고성군 거진읍 화진포길 280', 38.473891, 128.442935, '/places/hwajinpo-kim-il-sung-villa.webp', '사진: 고성군 관광포털', 'https://www.gwgs.go.kr/prog/tursmCn/tour/sub02_05/view.do?cntno=50', '숲속 돌계단 위에 선 성 모양의 김일성별장', 'https://www.gwgs.go.kr/prog/tursmCn/tour/sub02_05/view.do?cntno=50', 'https://map.naver.com/p/search/%EA%B9%80%EC%9D%BC%EC%84%B1%EB%B3%84%EC%9E%A5', true, 'exhibition', array['kids'], '화진포해변이 내려다보이는 솔숲 언덕의 2층 돌집으로, 선교사 셔우드 홀이 예배당으로 쓰던 건물을 1948~1950년 김일성 가족이 여름 휴양지로 썼어요. 전쟁 중 망가진 것을 2005년 옛 모습으로 복원해 당시 사진과 자료를 전시하고, 옥상에 오르면 바다와 거북 모양 섬 금구도가 보여요. 이기붕별장·이승만별장·셔우드 홀 문화공간과 통합 관람권 하나로 함께 둘러봐요.', '관람 09:00~18:00(동절기 09:00~17:30), 매표는 17:00(동절기 16:30)까지', '연중무휴', '통합 관람권 어른 4,000원, 청소년·어린이 3,000원(30명 이상 단체 3,000원·2,500원). 고성군민·65세 이상·국가유공자·1~3급 장애인·현역군인 무료', '033-680-3469', null, '별장까지 솔숲 사이 돌계단을 올라가야 해요.', null, 'open', null, null, '2026-11-21'),
  ('20000000-0000-4000-8000-000000000085', 'daejin-lighthouse', '대진등대', '등대', '동해안 최북단 곶 위에 선 팔각형 흰 등대', '강원특별자치도 고성군 현내면 한나루로4길 16-38', 38.503669, 128.428602, '/places/daejin-lighthouse.webp', '사진: 고성군 관광포털', 'https://www.gwgs.go.kr/prog/tursmCn/tour/sub02_09/view.do?cntno=101', '파도가 부서지는 바위 해안 너머 곶 위에 선 흰 대진등대', 'https://korean.visitkorea.or.kr/detail/ms_detail.do?cotid=c7c8ce83-d3b6-41f0-a401-1d0d16f3eb77', 'https://map.naver.com/p/search/%EB%8C%80%EC%A7%84%EB%93%B1%EB%8C%80', true, 'nature', array['free'], '대진항과 마차진 사이로 튀어나온 곶에 선 팔각형 콘크리트 등대로, 불빛이 12초마다 한 번씩 깜빡이며 먼바다의 배에 길을 알려요. 더 북쪽의 무인 등대인 저진도등도 이곳에서 원격으로 관리해요. 대진항 방파제와 바위 해안 쪽에서 등대와 바다를 함께 바라보기 좋고, 대진항 수산시장과 가까워 항구 구경과 묶어 들르기 맞아요.', null, null, null, null, null, '등탑 위 전망대는 2016년부터 안전 문제로 개방하지 않는다는 안내가 있어, 바깥에서 보는 곳으로 생각하세요.', null, 'open', null, null, '2026-11-21'),
  ('20000000-0000-4000-8000-000000000089', 'daejin-port', '대진항', '항구', '동해안 최북단 항구와 활어 파는 수산시장', '강원특별자치도 고성군 현내면 대진항길', 38.499593, 128.424775, '/places/daejin-port.webp', '사진: 고성군 관광포털', 'https://www.gwgs.go.kr/prog/tursmCn/tour/sub02_09/view.do?cntno=101', '산자락 아래 방파제가 감싼 대진항과 항구 마을', 'https://www.gwgs.go.kr/prog/tursmCn/tour/sub02_09/view.do?cntno=101', 'https://map.naver.com/p/search/%EB%8C%80%EC%A7%84%ED%95%AD', true, 'nature', array['free'], '동해안에서 가장 북쪽에 있는 항구로, 1920~30년대 축항과 동해북부선 철도가 놓이며 청어·정어리를 실어 나르던 거점이었어요. 지금은 항구 앞 대진항 수산시장에서 활어를 고르고, 방파제와 바로 옆 해상공원을 걸으며 북쪽 바다를 볼 수 있어요. 북쪽 곶의 대진등대가 보이고 통일전망대로 가는 길목이라 오가는 길에 들르기 좋아요.', null, null, '무료', '033-680-3411', '주차 가능', null, null, 'open', null, null, '2026-11-21'),
  ('20000000-0000-4000-8000-000000000091', 'masanbong', '마산봉', '산', '진부령 옆 백두대간 봉우리, 설경과 동해 조망', '강원특별자치도 고성군 간성읍 흘리 산1-108', 38.267627, 128.398921, '/places/masanbong.webp', '사진: 고성군 관광포털', 'https://www.gwgs.go.kr/prog/tursmCn/tour/sub02_0108/view.do?cntno=22', '단풍으로 물든 마산봉 자락과 산 아래 리조트 건물', 'https://www.gwgs.go.kr/prog/tursmCn/tour/sub02_0108/view.do?cntno=22', 'https://map.naver.com/p/search/%EB%A7%88%EC%82%B0%EB%B4%89', true, 'nature', array['free'], '진부령 가까이 백두대간 능선에 솟은 해발 1,052m 봉우리로, 정상에서 동해안이 내려다보이고 날씨가 맑으면 향로봉 너머 금강산 연봉까지 어렴풋이 보여요. 흘리 마을의 옛 알프스리조트 스키장 쪽이나 진부령 정상에서 오르는 길이 있고, 정상에서 백두대간 능선이 대간령 쪽으로 이어져요. 겨울 설경과 가을 단풍이 이름나 산행 경험이 있는 사람에게 맞아요.', null, null, '무료', '033-680-3382', null, '정상 부근 샘은 쓰기 어려우니 마실 물을 따로 챙기세요.
눈이 많이 오는 곳이라 겨울에는 아이젠 같은 겨울 산행 장비가 필요해요.
고성군은 봄(2월 1일~5월 15일)·가을(11월 1일~12월 15일) 산불조심기간에 일부 등산로를 막으니, 이 기간에는 입산할 수 있는지 먼저 확인하세요.', null, 'open', null, null, '2026-11-21'),
  ('20000000-0000-4000-8000-000000000057', 'munam-beach', '문암해변', '해변', '초승달 모양 해안선, 물이 얕은 가족 해변', '강원특별자치도 고성군 죽왕면 문암진리', 38.296517, 128.548638, '/places/munam-beach.webp', '사진: 고성군 관광포털', 'https://www.gwgs.go.kr/prog/tursmCn/tour/sub02_02/view.do?cntno=71', '구멍이 숭숭 파인 바위 사이로 들어오는 문암 앞바다', 'https://www.gwgs.go.kr/prog/tursmCn/tour/sub02_02/view.do?cntno=71', 'https://map.naver.com/p/search/%EB%AC%B8%EC%95%94%ED%95%B4%EB%B3%80', true, 'nature', array['free', 'kids'], '초승달처럼 휘어진 해안선을 따라 백사장이 이어지고, 물놀이할 수 있는 폭이 넓고 수심이 낮아 어린아이와 함께 오기 좋아요. 1991년 개장했으며 가까운 문암항에서 싱싱한 회를 맛볼 수 있어요. 교암해변·백도해변과 붙어 있어 해안을 따라 함께 둘러보기 좋아요.', '물놀이는 여름 개장 기간(7월 중순~8월 중순)에만 가능', null, '무료', '033-680-3356', null, '개장 기간이 아니면 안전요원이 없어 물에 들어가지 마세요.', null, 'open', null, null, '2026-11-21'),
  ('20000000-0000-4000-8000-000000000065', 'banam-beach', '반암해변', '해변', '거진 아래 반암리, 한적하고 낚시가 잘되는 해변', '강원특별자치도 고성군 거진읍 반암리', 38.421301, 128.463212, '/places/banam-beach.webp', '사진: 고성군 관광포털', 'https://www.gwgs.go.kr/prog/tursmCn/tour/sub02_02/view.do?cntno=72', '바위가 늘어선 얕은 물가와 반암해변 백사장', 'https://www.gwgs.go.kr/prog/tursmCn/tour/sub02_02/view.do?cntno=72', 'https://map.naver.com/p/search/%EB%B0%98%EC%95%94%ED%95%B4%EC%88%98%EC%9A%95%EC%9E%A5', true, 'nature', array['free'], '희고 고운 모래가 깔린 반암리 어촌 앞 해변으로, 다른 해변보다 한적하고 물이 맑으며 바다낚시가 잘돼 낚시객도 많이 찾아요. 반암항 낚시공원과 반암 캠핑장, 마을 민박촌이 가까워 묵어 가기 좋아요. 같은 반암리에 반려동물과 함께 들어갈 수 있는 유료 해변 ''반비치''가 따로 있어요.', '물놀이는 여름 개장 기간(7월 중순~8월 말)에만 가능', null, '무료', '033-680-3356', '해변 주차장(30분 무료, 이후 하루 5,000원)', '개장 기간이 아니면 안전요원이 없어 물에 들어가지 마세요.', null, 'open', null, null, '2026-11-21'),
  ('20000000-0000-4000-8000-000000000058', 'baekdo-beach', '백도해변', '해변', '하얀 섬 백도가 보이는, 솔숲과 캠핑장 있는 해변', '강원특별자치도 고성군 죽왕면 백도해변길 78', 38.301131, 128.546399, '/places/baekdo-beach.webp', '사진: 고성군 관광포털', 'https://www.gwgs.go.kr/prog/tursmCn/tour/sub02_02/view.do?cntno=73', '하늘에서 내려다본 백도해변의 휘어진 백사장과 옥빛 바다', 'https://www.gwgs.go.kr/prog/tursmCn/tour/sub02_02/view.do?cntno=73', 'https://map.naver.com/p/search/%EB%B0%B1%EB%8F%84%ED%95%B4%EB%B3%80', true, 'nature', array['free', 'kids'], '앞바다에 갈매기 배설물로 하얗게 보여 이름 붙은 작은 섬 백도가 떠 있고, 해변 서쪽에는 소나무 숲이 우거져 있어요. 활처럼 휜 백사장은 수심이 낮고 완만하며, 여름 개장 기간에는 해변 오토캠핑장을 운영해요. 주차장과 샤워장이 넓어 가족 단위로 많이 찾아요.', '물놀이는 여름 개장 기간(7월 중순~8월 중순)에만 가능', null, '무료', '033-680-3356', '해변 주차장(소형 약 100대, 하루 5,000원)', '오토캠핑장은 개장 기간에만 운영하고, 캠핑 트레일러는 들어갈 수 없어요.
개장 기간이 아니면 안전요원이 없어 물에 들어가지 마세요.', null, 'open', null, null, '2026-11-21'),
  ('20000000-0000-4000-8000-000000000080', 'baekseom-sea-observatory', '백섬 해상전망대', '전망', '바다 위 데크를 걸어 닿는 바위섬 전망대', '강원특별자치도 고성군 거진읍 거진리 산105', 38.449609, 128.467021, '/places/baekseom-sea-observatory.webp', '사진: 고성군 관광포털', 'https://www.gwgs.go.kr/prog/tursmCn/tour/sub03_03/view.do?cntno=128', '바위섬 옆으로 이어진 해상 데크와 전망대', 'https://www.gwgs.go.kr/prog/tursmCn/tour/sub03_03/view.do?cntno=128', 'https://map.naver.com/p/search/%EB%B0%B1%EC%84%AC%ED%95%B4%EC%83%81%EC%A0%84%EB%A7%9D%EB%8C%80', true, 'view', array['free', 'kids'], '해안도로에서 백섬(백암도)이라는 바위섬까지 바다 위로 137m 데크가 놓여 있고, 끝의 높이 25m 전망대는 바닥 일부가 투명한 강화유리예요. 북쪽으로 해금강과 금구도, 남쪽으로 거진항과 거진11리 해변이 펼쳐져 해 뜰 무렵 찾기 좋아요. 데크가 짧고 평탄해 10~20분이면 다녀올 수 있고, 위쪽 언덕의 거진등대와 함께 둘러보기 좋아요.', '4~10월 07:00~18:00, 11~3월 08:00~17:00', '연중무휴', '무료', '033-680-4092', '주차 가능', '개방 시간 밖에는 군 작전지역이라 들어갈 수 없어요.
길이 얼거나 파도가 높으면 출입이 막힐 수 있어요.', null, 'open', null, null, '2026-11-21'),
  ('20000000-0000-4000-8000-000000000061', 'bongsudae-beach', '봉수대해변', '해변', '국도 바로 옆, 서핑과 오토캠핑을 즐기는 해변', '강원특별자치도 고성군 죽왕면 오호리', 38.324387, 128.527389, '/places/bongsudae-beach.webp', '사진: 고성군 관광포털', 'https://www.gwgs.go.kr/prog/tursmCn/tour/sub02_02/view.do?cntno=74', '그늘막과 텐트가 놓인 봉수대해변 백사장과 앞바다 바위섬', 'https://www.gwgs.go.kr/prog/tursmCn/tour/sub02_02/view.do?cntno=74', 'https://map.naver.com/p/search/%EB%B4%89%EC%88%98%EB%8C%80%ED%95%B4%EC%88%98%EC%9A%95%EC%9E%A5', true, 'nature', array['free'], '고성 산불 피해 주민의 새 삶터를 위해 1997년 새로 연 해변으로, 국도 7호선 바로 옆이라 차에서 내려 곧장 백사장으로 걸어갈 수 있어요. 여름에는 서핑·카누 같은 해양 레포츠를 즐기는 사람이 많고, 여름철 오토캠핑장과 오호 VR해양모험관이 가까이 있어요. 삼포해변과 200m쯤 떨어져 있어 함께 들르기 좋아요.', '물놀이는 여름 개장 기간(7월 중순~8월 중순)에만 가능', null, '무료', '033-680-3356', '주차 가능', '개장 기간이 아니면 안전요원이 없어 물에 들어가지 마세요.', null, 'open', null, null, '2026-11-21'),
  ('20000000-0000-4000-8000-000000000053', 'bongpo-beach', '봉포해변', '해변', '속초 바로 위 봉포항 옆, 작은 바위가 흩어진 해변', '강원특별자치도 고성군 토성면 봉포리', 38.252861, 128.565967, '/places/bongpo-beach.webp', '사진: 고성군 관광포털', 'https://www.gwgs.go.kr/prog/tursmCn/tour/sub02_02/view.do?cntno=76', '파라솔이 줄지어 선 봉포해변과 앞바다의 작은 섬', 'https://www.gwgs.go.kr/prog/tursmCn/tour/sub02_02/view.do?cntno=76', 'https://map.naver.com/p/search/%EB%B4%89%ED%8F%AC%ED%95%B4%EB%B3%80', true, 'nature', array['free'], '속초시청에서 북쪽으로 3km쯤, 작은 봉포항을 끼고 있는 해변으로 모래사장 곳곳에 작은 바위가 흩어져 있어요. 방파제에서는 사철 바다낚시를 할 수 있고 앞바다에 무인도 ''하트섬''이 보이며, 봉포항에서 잡은 회를 맛볼 수 있어요. 북쪽으로 천진해변과 이어져 있어 함께 걷기 좋아요.', '물놀이는 여름 개장 기간(7월 초~8월 말)에만 가능', null, '무료', '033-680-3356', '주차 가능', '개장 기간이 아니면 안전요원이 없어 물에 들어가지 마세요.', null, 'open', null, null, '2026-11-21'),
  ('20000000-0000-4000-8000-000000000060', 'sampo-beach', '삼포해변', '해변', '솔숲과 넓은 백사장, 서핑 축제가 열린 국민관광지', '강원특별자치도 고성군 죽왕면 삼포해변길 15-4', 38.313717, 128.537125, '/places/sampo-beach.webp', '사진: 고성군 관광포털', 'https://www.gwgs.go.kr/prog/tursmCn/tour/sub02_02/view.do?cntno=78', '피서객과 파라솔로 가득한 삼포해변과 앞바다의 바위섬들', 'https://sampobeach.co.kr/', 'https://map.naver.com/p/search/%EC%82%BC%ED%8F%AC%ED%95%B4%EC%88%98%EC%9A%95%EC%9E%A5', true, 'nature', array['free', 'kids'], '1977년 개장해 1980년 국민관광지로 조성된 해변으로, 넓은 백사장 뒤로 소나무 숲이 우거져 있고 물이 깊지 않아요. 앞바다에 흑도·백도·호미섬 같은 섬이 있어 낚시터로도 알려져 있고, 서핑 축제가 열린 적도 있어요. 리조트와 민박촌이 가까워 묵어 가며 쉬기 좋아요.', '물놀이는 여름 개장 기간(7월 중순~8월 중순)에만 가능', null, '무료', '033-680-3356', '주차 가능', '개장 기간이 아니면 안전요원이 없어 물에 들어가지 마세요.', null, 'open', null, null, '2026-11-21'),
  ('20000000-0000-4000-8000-000000000082', 'seongindae', '성인대', '전망', '화암사 뒤 바위 봉우리, 울산바위 정면 조망', '강원특별자치도 고성군 토성면 신평리 산136-1', 38.219525, 128.462798, null, null, null, null, 'https://hwaamsa.com/pages/s2_10.php', 'https://map.naver.com/p/search/%EC%84%B1%EC%9D%B8%EB%8C%80', true, 'nature', array['free'], '화암사 옆 수바위에서 등산로로 1시간쯤 올라가면 닿는 너른 바위 봉우리로, 선인대라고도 불러요. 남쪽으로 조금 더 가면 나오는 신선대에서는 건너편 울산바위와 속초·고성 바다가 한눈에 펼쳐져 해돋이를 보기에도 좋아요. 화암사 일주문에서 수바위와 성인대를 거쳐 절로 돌아오는 ''금강산 화암사 숲길''(4.15km)로 오르내리며, 왕복 2시간쯤 걸려요.', null, null, '무료', null, '화암사 제1·제2주차장 이용', '왕복 2시간쯤 걸리는 산길이니 등산화와 물을 챙기세요.
고성군은 봄(2월 1일~5월 15일)·가을(11월 1일~12월 15일) 산불조심기간에 일부 등산로를 막으니, 이 기간에는 입산할 수 있는지 먼저 확인하세요.', null, 'open', null, null, '2026-11-21'),
  ('20000000-0000-4000-8000-000000000067', 'songjiho-lake', '송지호', '호수', '바닷물이 섞여 겨울에도 철새가 머무는 송지호 석호', '강원특별자치도 고성군 죽왕면 동해대로 6021', 38.337390, 128.510475, '/places/songjiho-lake.webp', '사진: 고성군 관광포털', 'https://www.gwgs.go.kr/prog/tursmCn/tour/sub02_0107/view.do?cntno=20', '바다와 모래톱 사이에 놓인 송지호와 누렇게 익은 논을 위에서 본 풍경', 'https://www.gwgs.go.kr/prog/tursmCn/tour/sub02_0107/view.do?cntno=20', 'https://map.naver.com/p/search/%EC%86%A1%EC%A7%80%ED%98%B8', true, 'nature', array['free', 'kids'], '바닷물이 섞인 둘레 약 6km의 석호로, 겨울에도 잘 얼지 않아 청둥오리·기러기와 천연기념물 고니가 머물다 가요. 호숫가 소나무 숲 산책로를 짧게 걷거나, 7번 국도 옆 송지호관망타워에 올라 호수와 바다를 함께 내려다볼 수 있어요. 바다 쪽 송지호해변과 죽도, 가까운 왕곡마을까지 묶어 하루 일정으로 돌기 좋아요.', null, null, '무료', '033-680-3362', '송지호관망타워 무료 주차장 이용', null, null, 'open', null, null, '2026-11-21'),
  ('20000000-0000-4000-8000-000000000090', 'songjiho-dulle-gil', '송지호 둘레길', '산책로', '호수·두백산·왕곡마을을 잇는 10.7km 걷기길', '강원특별자치도 고성군 죽왕면 오봉리 산14-1', 38.340150, 128.508289, '/places/songjiho-dulle-gil.webp', '사진: 고성군 관광포털', 'https://www.gwgs.go.kr/prog/tursmCn/tour/sub03_06/view.do?cntno=112', '나무 난간을 따라 소나무 숲 사이로 이어진 돌길', 'https://www.gwgs.go.kr/prog/tursmCn/tour/sub03_06/view.do?cntno=112', 'https://map.naver.com/p/search/%EC%86%A1%EC%A7%80%ED%98%B8%20%EB%91%98%EB%A0%88%EA%B8%B8', true, 'nature', array['free'], '고성갈래구경길 7코스로, 송지호관망타워에서 출발해 호수 북쪽 산책로와 두백산(244m) 정상, 왕곡마을, 호숫가 정자 송호정을 거쳐 송지호 남쪽 산책로와 송지호해변으로 이어져요. 전체 10.7km에 2시간 반쯤 걸리며, 두백산은 오르막이 있지만 처음 산에 오르는 사람도 갈 만한 높이예요. 호수와 숲, 옛 한옥 마을, 바다를 한 번에 걷고 싶은 사람에게 맞고, 짧게 걷고 싶다면 호숫가 구간만 다녀와도 돼요.', null, null, '무료', '033-680-3365', '출발지 송지호관망타워 무료 주차장 이용', '두백산 정상에 군사시설이 있으니 표지와 통제선을 따르세요.', null, 'open', null, null, '2026-11-21'),
  ('20000000-0000-4000-8000-000000000093', 'goseong-attraction-093', '송지호 비치코밍 전시·체험관', '체험시설', '고성군의 체험시설 매력을 직접 살펴볼 수 있는 여행 명소 송지호 비치코밍 전시·체험관입니다.', '강원특별자치도 고성군 일원', 38.335453, 128.515175, null, null, null, null, 'https://www.gwgs.go.kr/prog/tursmCn/tour/sub02_05/view.do?cntno=136', 'https://map.naver.com/p/search/%EC%86%A1%EC%A7%80%ED%98%B8%20%EB%B9%84%EC%B9%98%EC%BD%94%EB%B0%8D%20%EC%A0%84%EC%8B%9C%C2%B7%EC%B2%B4%ED%97%98%EA%B4%80', true, null, '{}', null, null, null, null, null, null, null, null, 'open', null, null, null),
  ('20000000-0000-4000-8000-000000000079', 'songjiho-observation-tower', '송지호관망타워', '전망', '송지호와 동해를 함께 내려다보는 철새 관망 타워', '강원특별자치도 고성군 죽왕면 동해대로 6021', 38.336271, 128.517653, '/places/songjiho-observation-tower.webp', '사진: 고성군 관광포털', 'https://www.gwgs.go.kr/prog/tursmCn/tour/sub02_05/view.do?cntno=49', '잔디밭 위에 선 원통형 송지호관망타워 건물', 'https://www.gwgs.go.kr/prog/tursmCn/tour/sub02_05/view.do?cntno=49', 'https://map.naver.com/p/search/%EC%86%A1%EC%A7%80%ED%98%B8%20%EC%B2%A0%EC%83%88%EA%B4%80%EB%A7%9D%ED%83%80%EC%9B%8C', true, 'view', array['free', 'kids'], '2007년 문을 연 관망 타워로, 엘리베이터로 위층에 오르면 송지호와 동해를 한눈에 내려다보며 망원경으로 철새 무리를 볼 수 있어요. 타워 앞에 2025년 10월 문을 연 송지호 비지터센터에는 해변 표류물과 조개껍데기로 소품을 만드는 비치코밍 전시·체험관이 있어요. 타워 입장과 전시 관람이 무료라 아이와 송지호를 둘러볼 때 먼저 들르기 좋아요.', '09:00~18:00(동절기 17:30까지), 입장 마감 17:20(동절기 16:40)', '연중무휴(비치코밍 체험관은 월요일 휴무)', '무료(비치코밍 체험은 별도: 대형 10,000원·소형 3,000원)', '033-680-3556', '무료', '비치코밍 체험·전시관은 매주 월요일 쉬고, 체험은 전화(033-680-4119) 예약만 받아요.', null, 'open', null, null, '2026-11-22'),
  ('20000000-0000-4000-8000-000000000062', 'songjiho-beach', '송지호해변', '해변', '대나무 섬 죽도를 마주한 2km 백사장 해변', '강원특별자치도 고성군 죽왕면 오호리', 38.330814, 128.527875, '/places/songjiho-beach.webp', '사진: 고성군 관광포털', 'https://www.gwgs.go.kr/prog/tursmCn/tour/sub02_02/view.do?cntno=79', '하늘에서 본 송지호해변 백사장과 앞바다의 섬 죽도', 'https://www.gwgs.go.kr/prog/tursmCn/tour/sub02_02/view.do?cntno=79', 'https://map.naver.com/p/search/%EC%86%A1%EC%A7%80%ED%98%B8%ED%95%B4%EB%B3%80', true, 'nature', array['free', 'kids'], '길이 2km쯤 되는 넓은 백사장 앞바다에 대나무와 기암괴석이 어우러진 섬 죽도가 떠 있고, 물이 맑고 얕아 가족 피서객이 많이 찾아요. 북쪽으로 500m쯤 가면 철새가 찾는 석호 송지호가 있고, 송지호오토캠핑장과 민박이 가까워 며칠 머물기 좋아요. 드라마 ''가을동화'' 촬영지로도 알려져 있어요.', '물놀이는 여름 개장 기간(7월 중순~8월 중순)에만 가능', null, '무료', '033-680-3356', '주차 가능', '개장 기간이 아니면 안전요원이 없어 물에 들어가지 마세요.', null, 'open', null, null, '2026-11-21'),
  ('20000000-0000-4000-8000-000000000083', 'subawi', '수바위', '자연', '화암사 앞 왕관 모양 바위와 쌀바위 전설', '강원특별자치도 고성군 토성면 신평리', 38.225404, 128.471688, '/places/subawi.webp', '사진: 고성군 관광포털', 'https://www.gwgs.go.kr/prog/tursmCn/tour/sub02_12/view.do?cntno=114', '단풍 든 숲 위로 솟은 수바위와 화암사 처마, 벤치', 'https://hwaamsa.com/pages/s2_2.php', 'https://map.naver.com/p/search/%EC%88%98%EB%B0%94%EC%9C%84', true, 'nature', array['free'], '화암사에서 남쪽으로 300m쯤 떨어진 곳에 우뚝 선 왕관 모양의 큰 바위로, 진표율사를 비롯한 스님들이 바위 위에서 수도했다고 전해요. 바위 구멍에서 끼니마다 쌀이 나오다가 욕심 낸 객승 때문에 끊겼다는 전설이 화암사(禾巖寺)라는 절 이름의 유래가 됐어요. 화암사에서 성인대로 오르는 등산로가 수바위를 지나므로, 절 구경 뒤 가볍게 들르거나 성인대 산행 길에 함께 보기 좋아요.', null, null, '무료', null, null, null, null, 'open', null, null, '2026-11-21'),
  ('20000000-0000-4000-8000-000000000087', 'goseong-attraction-087', '아야진등대', '등대', '고성군의 등대 매력을 직접 살펴볼 수 있는 여행 명소 아야진등대입니다.', '강원특별자치도 고성군 일원', 38.274351, 128.555952, null, null, null, null, 'https://www.gangwon.to/page/gwtour2022/images/map/tourmap_17.pdf', 'https://map.naver.com/p/search/%EC%95%84%EC%95%BC%EC%A7%84%EB%93%B1%EB%8C%80', true, null, '{}', null, null, null, null, null, null, null, null, 'open', null, null, null),
  ('20000000-0000-4000-8000-000000000055', 'ayajin-beach', '아야진해변', '해변', '기차바위 스노클링 명소, 바위와 옥빛 바다 해변', '강원특별자치도 고성군 토성면 아야진해변길 157', 38.275872, 128.553385, '/places/ayajin-beach.webp', '사진: 고성군 관광포털', 'https://www.gwgs.go.kr/prog/tursmCn/tour/sub02_02/view.do?cntno=80', '평상이 줄지어 놓인 아야진해변의 하얀 백사장과 얕은 바다', 'https://www.gwgs.go.kr/prog/tursmCn/tour/sub02_02/view.do?cntno=80', 'https://map.naver.com/p/search/%EC%95%84%EC%95%BC%EC%A7%84%ED%95%B4%EB%B3%80', true, 'nature', array['free', 'kids'], '크고 작은 바위와 맑은 바다, 고운 백사장이 어우러진 해변으로, 해안에서 30m까지 수심이 1.5~2m쯤으로 완만해요. 바위가 기차처럼 길게 이어진 ''기차바위'' 주변은 스노클링 명소로 꼽히고, 항구 주변 갯바위에서는 낚시도 할 수 있어요. 군부대와 협의해 여름에만 한시적으로 문을 여는 해변이에요.', '물놀이는 여름 개장 기간(6월 중순~8월 말)에만 가능', null, '무료', '033-680-3356', '해변 주차장(개장 기간 5,000원)', '개장 기간이 아니면 안전요원이 없어 물에 들어가지 마세요.', null, 'open', null, null, '2026-11-21'),
  ('20000000-0000-4000-8000-000000000077', 'hwajinpo-syngman-rhee-villa', '이승만별장(이승만대통령 화진포기념관)', '역사관', '화진포 호숫가의 이승만 별장과 기념관', '강원특별자치도 고성군 현내면 이승만별장길 33', 38.470974, 128.436767, '/places/hwajinpo-syngman-rhee-villa.webp', '사진: 고성군 관광포털', 'https://www.gwgs.go.kr/prog/tursmCn/tour/sub02_05/view.do?cntno=51', '철쭉이 핀 언덕 위 이승만별장 건물', 'https://www.gwgs.go.kr/prog/tursmCn/tour/sub02_05/view.do?cntno=51', 'https://map.naver.com/p/search/%EC%9D%B4%EC%8A%B9%EB%A7%8C%EB%B3%84%EC%9E%A5', true, 'exhibition', '{}', '화진포 호수가 내려다보이는 언덕의 이승만 전 대통령 별장과, 그 뒤에 새로 지은 기념관이에요. 별장에는 침실·거실·집무실과 안경·여권·편지 같은 유품이, 기념관에는 친필 휘호와 옷, 관련 도서가 전시돼 있어요. 바다 쪽 김일성별장과 1km쯤 떨어져 있고, 같은 통합 관람권으로 들어가요.', '관람 09:00~18:00(동절기 09:00~17:30), 매표는 17:00(동절기 16:30)까지', '연중무휴', '통합 관람권 어른 4,000원, 청소년·어린이 3,000원(30명 이상 단체 3,000원·2,500원). 고성군민·65세 이상·국가유공자·1~3급 장애인·현역군인 무료', '033-680-3677', null, null, null, 'open', null, null, '2026-11-21'),
  ('20000000-0000-4000-8000-000000000059', 'jajakdo-beach', '자작도해변', '해변', '파도에 다듬어진 바위가 흩어진 송림 해변', '강원특별자치도 고성군 죽왕면 자작도선사길', 38.308557, 128.542756, '/places/jajakdo-beach.webp', '사진: 고성군 미디어홍보관', 'https://www.gwgs.go.kr/prog/photodbCate/12801/view.do?downloadType=photo&cateNo=50', '하늘에서 본 자작도해변의 휘어진 백사장과 물속 바위들', 'https://korean.visitkorea.or.kr/detail/ms_detail.do?cotid=a9c08346-b320-45e6-821b-ee2b5d638409', 'https://map.naver.com/p/search/%EC%9E%90%EC%9E%91%EB%8F%84%ED%95%B4%EB%B3%80', true, 'nature', array['free', 'kids'], '초승달 모양 해안선을 따라 희고 고운 백사장이 이어지고, 양쪽 끝에는 파도에 매끈하게 다듬어진 바위들이 흩어져 있어요. 수심이 낮고 물놀이 폭이 넓어 아이와 함께 오기 좋으며, 바위 주변에는 스노클링 포인트도 있어요. 1991년 개장했고 해변 뒤로 소나무 숲이 이어져요.', '물놀이는 여름 개장 기간(7월 중순~8월 중순)에만 가능', null, '무료', '033-680-3362', '주차 가능', '개장 기간이 아니면 안전요원이 없어 물에 들어가지 마세요.', null, 'open', null, null, '2026-11-21'),
  ('20000000-0000-4000-8000-000000000084', 'jinburyeong-art-museum', '고성군 진부령미술관', '미술관', '진부령 고갯마루, 이중섭 전시실이 있는 미술관', '강원특별자치도 인제군 북면 진부령로 663', 38.265505, 128.358528, '/places/jinburyeong-art-museum.webp', '사진: 고성군 관광포털', 'https://www.gwgs.go.kr/prog/tursmCn/tour/sub02_05/view.do?cntno=45', '그림이 걸린 진부령미술관의 넓은 전시실', 'https://www.gwgs.go.kr/prog/tursmCn/tour/sub02_05/view.do?cntno=45', 'https://map.naver.com/p/search/%EC%A7%84%EB%B6%80%EB%A0%B9%EB%AF%B8%EC%88%A0%EA%B4%80', true, 'exhibition', array['free', 'indoor'], '진부령 고개 정상(해발 520m)에 고성군이 운영하는 작은 미술관으로, 화가 이중섭을 다룬 전시실과 기획 전시실이 있어요. 행정구역은 인제군 북면이지만 고성군 관광 누리집에 올라 있는 고성군 시설이고, 진부령을 넘어 고성과 내륙을 오가는 길에 잠시 들르기 좋아요.', '하절기 09:00~18:00, 동절기 09:00~17:00', '매주 월요일, 1월 1일, 설날·추석 당일', '무료', '033-681-7667', '무료', null, null, 'open', null, null, '2026-11-22'),
  ('20000000-0000-4000-8000-000000000052', 'cheonjin-beach', '천진해변', '해변', '천진항 옆, 물이 얕고 파도가 잔잔한 초승달 해변', '강원특별자치도 고성군 토성면 천진리', 38.259935, 128.560305, '/places/cheonjin-beach.webp', '사진: 고성군 관광포털', 'https://www.gwgs.go.kr/prog/tursmCn/tour/sub02_02/view.do?cntno=81', '초록 그늘막이 줄지어 선 천진해변 백사장과 해변 마을', 'https://www.gwgs.go.kr/prog/tursmCn/tour/sub02_02/view.do?cntno=81', 'https://map.naver.com/p/search/%EC%B2%9C%EC%A7%84%ED%95%B4%EB%B3%80', true, 'nature', array['free', 'kids'], '천진항과 붙어 초승달 모양으로 휘어진 해변으로, 전체적으로 물이 얕고 파도가 잔잔해 아이들이 놀기 좋아요. 방파제 낚시와 천진항 활어회를 함께 즐길 수 있고, 2025년 여름에는 섭죽 만들기 같은 마을 체험 축제가 열리기도 했어요. 고성에서 해마다 일찍 문을 여는 해변 가운데 하나예요.', '물놀이는 여름 개장 기간(6월 하순~8월 말)에만 가능', null, '무료(샤워장·파라솔·야영장은 유료)', '033-680-3356', '주차 가능', '개장 기간이 아니면 안전요원이 없어 물에 들어가지 마세요.', null, 'open', null, null, '2026-11-21'),
  ('20000000-0000-4000-8000-000000000069', 'cheonganjeong', '청간정', '정자', '청간천 하구 바닷가 절벽 위, 관동팔경의 정자', '강원특별자치도 고성군 토성면 동해대로 5110', 38.264432, 128.558371, '/places/cheonganjeong.webp', '사진: 고성군 관광포털', 'https://www.gwgs.go.kr/prog/tursmCn/tour/sub02_0104/view.do?cntno=16', '소나무 숲 위로 바다와 백사장을 내려다보는 청간정', 'https://www.gwgs.go.kr/prog/tursmCn/tour/sub02_0104/view.do?cntno=16', 'https://map.naver.com/p/search/%EC%B2%AD%EA%B0%84%EC%A0%95', true, 'nature', array['free'], '청간천이 바다로 흘러드는 바닷가 바위 절벽 위에 선 2층 정자로, 예부터 관동팔경의 하나로 꼽혀 왔어요. 소나무 숲길을 조금 걸어 오르면 동해와 청간해변이 한눈에 들어오고, 정자 안에는 이승만 전 대통령이 쓴 현판이 걸려 있어요. 해돋이 명소라 이른 아침에 찾기 좋아요.', null, null, '무료', '033-680-3368', null, null, null, 'open', null, null, '2026-11-21'),
  ('20000000-0000-4000-8000-000000000054', 'cheongan-beach', '청간해변', '해변', '관동팔경 청간정 앞까지 이어진 마을 해변', '강원특별자치도 고성군 토성면 청간리', 38.268125, 128.556525, '/places/cheongan-beach.webp', '사진: 고성군 관광포털', 'https://www.gwgs.go.kr/prog/tursmCn/tour/sub02_02/view.do?cntno=82', '너른 바위 사이 얕은 물에서 물놀이하는 청간해변', 'https://www.gwgs.go.kr/prog/tursmCn/tour/sub02_02/view.do?cntno=82', 'https://map.naver.com/p/search/%EC%B2%AD%EA%B0%84%ED%95%B4%EB%B3%80', true, 'nature', array['free'], '청간리 마을 앞 해안선을 따라 희고 고운 모래가 깔린 해변으로, 관동팔경 가운데 하나인 정자 청간정 바로 앞까지 백사장이 열려 있어요. 물놀이 뒤에 바위 언덕 위 청간정에 올라 해변을 내려다보기 좋고, 설악권 콘도 지역과 가까워 숙소를 구하기 쉬워요.', '물놀이는 여름 개장 기간(7월 중순~8월 하순)에만 가능', null, '무료', '033-680-3356', '주차 가능', '개장 기간이 아니면 안전요원이 없어 물에 들어가지 마세요.', null, 'open', null, null, '2026-11-21'),
  ('20000000-0000-4000-8000-000000000071', 'goseong-unification-observatory', '통일전망대', '전망', '금강산과 해금강을 바라보는 최북단 통일전망대', '강원특별자치도 고성군 현내면 통일전망대로 457', 38.586619, 128.374900, '/places/goseong-unification-observatory.webp', '사진: 고성군 관광포털', 'https://www.gwgs.go.kr/prog/tursmCn/tour/sub02_0106/view.do?cntno=19', '통일전망대에서 내려다본 북쪽 해안선과 백사장, 먼 산줄기', 'https://www.gwgs.go.kr/prog/tursmCn/tour/sub02_0106/view.do?cntno=19', 'https://map.naver.com/p/search/%ED%86%B5%EC%9D%BC%EC%A0%84%EB%A7%9D%EB%8C%80', true, 'view', array['kids'], '동해안 최북단 해발 70m 고지에서 금강산 자락과 해금강 일대를 바라보는 전망대로, 2018년 높이 34m의 통일전망타워가 새로 섰어요. 4층 전망대에서 해금강의 섬과 바위를 볼 수 있고, 같은 구역의 6.25전쟁체험전시관과 DMZ박물관도 추가 요금 없이 함께 둘러봐요. 민통선 안이라 출입신고소에서 신고와 짧은 안보교육을 받은 뒤 자가용으로 10분쯤 이동해 들어가요.', '출입신고 09:00~16:50(7월 15일~8월 20일은 17:50, 11~2월은 15:50까지), 신고 마감 뒤 1시간까지 관람', '연중무휴', '어른 3,000원, 학생·65세 이상 1,500원(30명 이상 단체 2,000원·1,200원·1,000원), 6.25전쟁체험전시관 포함. 고성군민 50% 할인, 국가유공자·1~3급 장애인 무료', '033-682-0088', '유료(출입신고소에서 함께 결제: 9인승 이하 5,000원, 10인승 이상 6,000원)', '민통선 안이라 먼저 통일안보공원 출입신고소(현내면 금강산로 481)에서 출입신고·요금 결제와 안보교육 영상(약 8분)을 마쳐야 들어갈 수 있어요. 차 한 대에 대표자 1명의 신분증이 있으면 돼요.
''고성군통일전망대 출입신고'' 앱으로 방문자 등록을 미리 해 두면 신고소에서는 결제와 교육만 받으면 돼요.
자가용으로만 들어갈 수 있고 도보·자전거·이륜차·화물차는 출입할 수 없어요. DMZ박물관까지 합쳐 4시간 안에 둘러보고 나와야 해요.', null, 'open', null, null, '2026-11-22'),
  ('20000000-0000-4000-8000-000000000075', 'hwajinpo-sherwood-hall', '화진포 셔우드 홀 문화공간', '박물관', '셔우드 홀 가족과 첫 크리스마스 씰 이야기 전시관', '강원특별자치도 고성군 거진읍 화진포길 278', 38.472164, 128.443693, '/places/hwajinpo-sherwood-hall.webp', '사진: 고성군 관광포털', 'https://www.gwgs.go.kr/prog/tursmCn/tour/sub02_05/view.do?cntno=138', '갈색 외벽에 이름이 걸린 화진포 셔우드 홀 문화공간 건물', 'https://korean.visitkorea.or.kr/detail/ms_detail.do?cotid=608ea19a-281a-4840-a2e1-930d0e1f9c9f', 'https://map.naver.com/p/search/%ED%99%94%EC%A7%84%ED%8F%AC%EC%83%9D%ED%83%9C%EB%B0%95%EB%AC%BC%EA%B4%80', true, 'exhibition', array['indoor'], '옛 화진포생태박물관 건물을 고쳐 2025년 6월 문을 연 전시관으로, 조선에서 의료·교육 선교를 한 로제타 홀과 아들 셔우드 홀 가족의 삶을 소개해요. 1층은 로제타 홀, 2층은 셔우드 홀과 아내 매리언 홀, 3층은 셔우드 홀이 처음 펴낸 크리스마스 씰 전시와 카페로 꾸몄고, 옥상 전망대에서 화진포 호수와 해변이 보여요. 김일성별장 가까이에 있어 역사안보전시관과 같은 통합 관람권으로 함께 둘러봐요.', '관람 09:00~18:00(동절기 09:00~17:30), 매표는 17:00(동절기 16:30)까지', '연중무휴', '통합 관람권 어른 4,000원, 청소년·어린이 3,000원(30명 이상 단체 3,000원·2,500원). 고성군민·65세 이상·국가유공자·1~3급 장애인·현역군인 무료', '033-680-4391', null, null, null, 'open', null, null, '2026-11-21'),
  ('20000000-0000-4000-8000-000000000076', 'goseong-attraction-076', '화진포역사안보전시관', '전시관', '고성군의 전시관 매력을 직접 살펴볼 수 있는 여행 명소 화진포역사안보전시관입니다.', '강원특별자치도 고성군 일원', 38.380373, 128.467600, null, null, null, null, 'https://korean.visitkorea.or.kr/detail/ms_detail.do?cotid=ebf95a62-014a-4458-a0e0-cfd24d43bcd6', 'https://map.naver.com/p/search/%ED%99%94%EC%A7%84%ED%8F%AC%EC%97%AD%EC%82%AC%EC%95%88%EB%B3%B4%EC%A0%84%EC%8B%9C%EA%B4%80', true, null, '{}', null, null, null, null, null, null, null, null, 'open', null, null, null),
  ('20000000-0000-4000-8000-000000000066', 'hwajinpo-beach', '화진포해변', '해변', '밟으면 소리 나는 모래, 화진포 호수와 맞닿은 해변', '강원특별자치도 고성군 현내면 초도리 99', 38.479468, 128.438825, '/places/hwajinpo-beach.webp', '사진: 고성군 관광포털', 'https://www.gwgs.go.kr/prog/tursmCn/tour/sub02_02/view.do?cntno=85', '언덕 위에서 내려다본 화진포해변의 긴 백사장과 맑은 바다', 'https://www.gwgs.go.kr/prog/tursmCn/tour/sub02_02/view.do?cntno=85', 'https://map.naver.com/p/search/%ED%99%94%EC%A7%84%ED%8F%AC%ED%95%B4%EC%88%98%EC%9A%95%EC%9E%A5', true, 'nature', array['free', 'kids'], '조개껍질과 바위가 부서져 생긴 고운 모래가 1.7km쯤 이어지는 해변으로, 밟으면 모래에서 소리가 나는 것으로 알려져 있어요. 앞바다에는 대나무 숲이 덮인 섬 금구도가 보이고, 뒤로는 화진포 호수와 김일성별장·이승만별장·화진포해양박물관이 가까워 함께 둘러보기 좋아요. 수심이 1~1.5m로 얕아요.', '물놀이는 여름 개장 기간(7월 중순~8월 중순)에만 가능', null, '무료(샤워장·야영장은 유료)', '033-680-3356', '해변 주차장(소형 약 430대)', '개장 기간이 아니면 안전요원이 없어 물에 들어가지 마세요.', null, 'open', null, null, '2026-11-21'),
  ('20000000-0000-4000-8000-000000000074', 'hwajinpo-marine-museum', '화진포해양박물관', '박물관', '패류 전시와 터널 수조가 있는 화진포 해양박물관', '강원특별자치도 고성군 현내면 화진포길 412', 38.481393, 128.435717, '/places/hwajinpo-marine-museum.webp', '사진: 고성군 관광포털', 'https://www.gwgs.go.kr/prog/tursmCn/tour/sub02_05/view.do?cntno=54', '물고기 떼가 헤엄치는 화진포해양박물관의 대형 수조', 'https://www.gwgs.go.kr/prog/tursmCn/tour/sub02_05/view.do?cntno=54', 'https://map.naver.com/p/search/%ED%99%94%EC%A7%84%ED%8F%AC%ED%95%B4%EC%96%91%EB%B0%95%EB%AC%BC%EA%B4%80', true, 'exhibition', array['kids', 'indoor'], '화진포해변 옆의 박물관으로, 조개·고둥 같은 패류의 진화와 생태를 다루는 패류동과 고성 바다 생물을 수조로 보여 주는 수족관동으로 나뉘어요. 터널형 수조와 디지털 스케치 같은 체험 전시가 있어 아이와 가기 좋고, 패류동 3층 카페에서는 화진포 호수와 바다를 내려다볼 수 있어요. 리모델링을 마치고 2024년 11월 다시 문을 열었어요.', '관람 09:00~18:00, 매표는 17:00까지(매표소는 패류동)', '연중무휴', '어른 5,000원, 청소년·군인 4,000원, 어린이(7~12세) 3,000원, 65세 이상 2,500원. 고성군민·6세 이하·국가유공자·등록장애인 무료', '033-680-3674', null, null, null, 'open', null, null, '2026-11-21'),
  ('20000000-0000-4000-8000-000000000068', 'hwajinpo-lake', '화진포호', '호수', '해당화에서 이름 딴 동해안 최대 석호와 별장 숲', '강원특별자치도 고성군 거진읍 화진포길 280', 38.469645, 128.438715, '/places/hwajinpo-lake.webp', '사진: 고성군 관광포털', 'https://www.gwgs.go.kr/prog/tursmCn/tour/sub02_0103/view.do?cntno=15', '숲 우거진 산 사이로 구름이 비치는 화진포호와 멀리 보이는 바다', 'https://www.gwgs.go.kr/prog/tursmCn/tour/sub02_0103/view.do?cntno=15', 'https://map.naver.com/p/search/%ED%99%94%EC%A7%84%ED%8F%AC%ED%98%B8', true, 'nature', array['free'], '둘레 약 16km로 동해안에서 가장 큰 자연 호수이며, 호숫가에 해당화가 많이 핀 데서 이름이 붙었어요. 울창한 소나무 숲에 둘러싸여 이승만·이기붕·김일성 별장 같은 옛 별장이 호숫가와 바닷가에 남아 있고, 겨울에는 넓은 갈대밭에 고니와 청둥오리가 날아들어요. 호수 옆 응봉에 오르면 호수와 화진포해변이 한눈에 들어와 별장 관람과 묶어 반나절 둘러보기 좋아요.', null, null, '무료(주변 역사안보전시관·박물관은 별도 요금)', '033-680-3677', null, null, null, 'open', null, null, '2026-11-21'),
  ('20000000-0000-4000-8000-000000000072', 'goseong-dmz-museum', 'DMZ박물관', '박물관', '민통선 안에서 DMZ의 역사와 생태를 보는 박물관', '강원특별자치도 고성군 현내면 통일전망대로 369', 38.576319, 128.382700, '/places/goseong-dmz-museum.webp', '사진: 고성군 관광포털', 'https://www.gwgs.go.kr/prog/tursmCn/tour/sub02_05/view.do?cntno=46', '유리 외벽에 DMZ 글자가 붙은 DMZ박물관 입구', 'https://www.dmzmuseum.com/', 'https://map.naver.com/p/search/DMZ%EB%B0%95%EB%AC%BC%EA%B4%80', true, 'exhibition', array['kids', 'indoor'], '통일전망대로 올라가는 길목에 2009년 문을 연 박물관으로, 한국전쟁 전후와 휴전선이 생긴 과정, 이산의 아픔, 사람 손이 닿지 않은 비무장지대의 생태를 전시물과 영상으로 보여 줘요. 관람료와 박물관 주차는 무료지만, 통일전망대 출입신고와 입장료·주차요금을 먼저 내야 들어갈 수 있어요. 둘러보는 데 40분~1시간 30분쯤 걸려요.', '하절기(3~10월) 09:00~18:00, 동절기(11~2월) 09:00~17:00, 마감 1시간 전까지 입장', '매주 월요일, 1월 1일(월요일이 공휴일이면 다음 평일)', '무료(통일전망대 입장료·주차요금을 내고 출입신고를 해야 들어갈 수 있음)', '033-681-0625', '박물관 주차장 무료(통일전망대 출입 주차요금은 별도)', '민통선 안이라 먼저 통일안보공원 출입신고소(현내면 금강산로 481)에서 출입신고·요금 결제와 안보교육 영상(약 8분)을 마쳐야 들어갈 수 있어요. 차 한 대에 대표자 1명의 신분증이 있으면 돼요.
''고성군통일전망대 출입신고'' 앱으로 방문자 등록을 미리 해 두면 신고소에서는 결제와 교육만 받으면 돼요.
자가용으로만 들어갈 수 있고, 출입신고는 통일전망대 마감 시각(11~2월 15:50, 3~10월 대부분 16:50)까지라 늦게 가면 박물관이 열려 있어도 못 들어가요.', null, 'open', null, null, '2026-11-22'),
  ('20000000-0000-4000-8000-000000000012', 'dinosaur-ridge', '공룡능선', '산', '마등령과 신선대 사이를 잇는 설악산의 험한 바위 능선', '강원특별자치도 속초시 설악동 설악산국립공원', 38.150235, 128.442923, '/places/dinosaur-ridge.webp', '사진: 속초시 관광 누리집', 'https://www.sokcho.go.kr/ct/tour/attraction/nature?contentSeq=82', '구름 위로 솟은 설악산 공룡능선의 바위 봉우리', 'https://www.sokcho.go.kr/ct/tour/attraction/nature?contentSeq=82', 'https://map.naver.com/p/search/%EA%B3%B5%EB%A3%A1%EB%8A%A5%EC%84%A0', true, 'nature', array['free'], '마등령에서 신선대까지 약 5km 이어지는 설악산의 대표 암릉으로, 해발 1,000m가 넘는 봉우리를 여러 번 오르내리며 외설악과 내설악을 함께 내려다봐요. 소공원에서 비선대·마등령으로 올라 능선을 지나 천불동계곡으로 내려오는 원점 코스는 약 20km라 하루를 통째로 쓰는 장거리 산행이에요. 산행 경험과 장비를 갖춘 사람에게 맞고, 가벼운 나들이 코스로는 맞지 않아요.', null, '봄·가을 산불조심기간에 고지대 탐방로로 통제(가을은 11월 중순~12월 중순 무렵)', '무료', '033-801-0900', '설악산 소공원 유료 주차장 이용', '급경사 바위 구간이 계속 이어지는 매우 어려운 코스예요.
통제 기간에 탐방로가 아닌 길로 들어가면 과태료를 내요.
하루 안에 내려오려면 이른 새벽에 출발해야 해요.', null, 'open', null, null, '2026-11-21'),
  ('20000000-0000-4000-8000-000000000027', 'national-mountaineering-school', '국립등산학교', '체험시설', '국립 인공암벽장과 등산·클라이밍 교육 과정을 운영하는 학교', '강원특별자치도 속초시 미시령로 3056', 38.202195, 128.541643, '/places/national-mountaineering-school.webp', '사진: 속초시 관광 누리집', 'https://www.sokcho.go.kr/ct/tour/attraction/experience?contentSeq=120', '설악산 봉우리를 배경으로 선 국립속초등산학교 건물', 'https://komount.or.kr/nationalmschool/', 'https://map.naver.com/p/search/%EA%B5%AD%EB%A6%BD%EB%93%B1%EC%82%B0%ED%95%99%EA%B5%90', true, 'experience', array['reservation'], '한국등산·트레킹지원센터가 운영하는 등산 교육 기관으로, 실내외 인공암벽장과 강의실·숙소를 갖추고 있어요. 일반인은 2시간 안팎의 스포츠클라이밍 기초교육이나 1박 2일 이상의 등산·암벽·빙벽 과정에 신청해 참여할 수 있어요. 인공암벽장 자유 이용은 장비와 경험을 갖춘 사람을 대상으로 하며 예약제로 운영해요. 실외 암벽과 야외 교육은 날씨에 따라 일정이 바뀔 수 있어요.', '인공암벽장 10:00~17:00. 스포츠클라이밍 기초교육은 2~11월 수·목요일 10:00~11:30(무료), 14:00~16:30(유료)', '인공암벽장 매주 월요일 휴장', '인공암벽장 시설사용료 무료 · 스포츠클라이밍 기초교육 90분 무료, 150분 17,820원 · 숙박형 교육은 과정별(레츠고 산에가자 1박 2일 51,000원 등)', '033-632-6650', null, '인공암벽장 자유 이용은 숲나들e에서 사전 예약해야 하고, 암벽화·안전벨트·로프 등 개인 장비가 없으면 이용할 수 없어요.
등반 경험이 없는 가족·청소년은 인공암벽장 자유 이용이 불가하며, 학교 교육 프로그램으로 체험해야 해요.
스포츠클라이밍 기초교육은 전화(033-632-6653)로 날짜와 인원을 예약하며, 회당 5명 이상일 때 진행해요.
내부 교육 일정, 기상 악화, 시설 보수로 일정이 취소되거나 시간이 바뀔 수 있어요.', 'https://www.foresttrip.go.kr/indvz/main.do?hmpgId=ID07030001', 'open', '스포츠클라이밍 기초교육은 2월부터 11월까지만 진행해요.', null, '2026-11-21'),
  ('20000000-0000-4000-8000-000000000007', 'national-mountain-museum', '국립산악박물관', '박물관', '산악 역사 전시와 암벽·고산 체험을 하는 무료 국립 박물관', '강원특별자치도 속초시 미시령로 3054', 38.202796, 128.540500, '/places/national-mountain-museum.webp', '사진: 속초시 관광 누리집', 'https://www.sokcho.go.kr/ct/tour/attraction/experience?contentSeq=114', '천장에 거꾸로 매달린 암벽 조형물이 있는 국립산악박물관 로비', 'https://www.komount.or.kr/nmm/', 'https://map.naver.com/p/search/%EA%B5%AD%EB%A6%BD%EC%82%B0%EC%95%85%EB%B0%95%EB%AC%BC%EA%B4%80', true, 'exhibition', array['indoor', 'kids', 'free'], '한국 등산의 역사와 산악인의 기록을 전시하는 국립 박물관으로 관람료가 없어요. 낮은 실내 암벽과 VR 등반 체험은 예약 없이 이용하고, 저산소 환경을 겪어 보는 고산체험실은 사전 예약으로 운영해요. 실내 시설이라 날씨와 관계없이 아이와 함께 1시간 남짓 둘러보기에 맞아요.', '화~일요일 09:00~18:00', '매주 월요일(공휴일이면 개관), 1월 1일, 설·추석 연휴', '무료', '033-638-4459', null, '고산체험실(저산소 체험)은 숲나들e 온라인 사전 예약으로만 운영하며 전화 예약은 받지 않아요.
고산체험은 10세 이상(보호자 동반)만 할 수 있고 노약자는 이용이 제한돼요.
실내 암벽 체험은 공용 암벽화를 신으므로 개인 양말을 챙겨야 해요.
6세 이하 어린이는 보호자와 함께 입장해야 하고 반려동물은 들어갈 수 없어요.', 'https://www.foresttrip.go.kr/indvz/main.do?hmpgId=ID07030002', 'open', null, null, '2026-11-21'),
  ('20000000-0000-4000-8000-000000000013', 'gwongeumseong', '권금성', '전망', '설악케이블카로 오르는 해발 약 700m 봉우리의 옛 산성 터', '강원특별자치도 속초시 설악동 설악산국립공원', 38.163966, 128.485127, '/places/gwongeumseong.webp', '사진: 속초시 관광 누리집', 'https://www.sokcho.go.kr/ct/tour/attraction/nature?contentSeq=81', '단풍 든 산 사이로 솟은 권금성 바위 봉우리', 'https://www.sokcho.go.kr/ct/tour/attraction/nature?contentSeq=81', 'https://map.naver.com/p/search/%EA%B6%8C%EA%B8%88%EC%84%B1', true, 'nature', array['kids'], '소공원에서 설악케이블카를 타고 5분쯤 오르는 바위 봉우리로, 두 장수가 하룻밤에 쌓았다는 이야기가 전해지는 옛 산성 터가 남아 있어요. 상부 승강장에서 계단을 10분 정도 오르면 봉화대가 나오고, 외설악 봉우리와 속초 시내, 멀리 동해까지 함께 보여요. 걸어서 오르내리는 길이 없어 왕복 케이블카로만 갈 수 있어, 산행 부담 없이 설악산 전망을 보고 싶은 가족에게 맞아요.', '케이블카 운행시간은 계절·날씨에 따라 달라 설악케이블카 홈페이지에 날마다 게시', '정기 휴무 없음(강풍·악천후 때 케이블카 운행 중단)', '케이블카 왕복 대인 16,000원 · 소인(37개월~초등학생) 12,000원', '033-636-4300', '설악산 소공원 유료 주차장 이용', '승차권은 당일 현장에서 왕복으로만 팔고, 주말·단풍철에는 대기가 길어질 수 있어요.
마지막 편을 타면 권금성에 머무는 시간이 20분 정도뿐이에요.
유모차는 탈 수 없어 탑승장 옆 무료 보관소에 맡겨야 해요.', null, 'open', null, null, '2026-11-21'),
  ('20000000-0000-4000-8000-000000000049', 'geumganggul-cave', '금강굴', '동굴', '비선대 위 장군봉 중턱 절벽에 있는 자연 석굴', '강원특별자치도 속초시 설악동 설악산국립공원', 38.164711, 128.464701, '/places/geumganggul-cave.webp', '사진: Sohyeon Bak, CC BY-SA 3.0 (위키미디어 공용) · 원본에서 잘라냄', 'https://commons.wikimedia.org/wiki/File:%EA%B8%88%EA%B0%95%EA%B5%B4.jpg', '깎아지른 바위 절벽을 따라 금강굴로 오르는 철계단', 'https://korean.visitkorea.or.kr/detail/ms_detail.do?cotid=3e0da4de-c6aa-4216-bdf9-2f7aef816eb2', 'https://map.naver.com/p/search/%EA%B8%88%EA%B0%95%EA%B5%B4', true, 'nature', array['free'], '비선대 서쪽 장군봉 중턱, 해발 약 600m 암벽에 난 자연 동굴로, 원효대사가 수도했다고 전해지며 지금은 신흥사에 딸린 암자예요. 소공원에서 와선대·비선대를 지나 약 3.6km, 편도 2시간쯤 걸리고, 비선대부터는 계단이 이어지는 가파른 오르막이에요. 굴 앞에서 천불동계곡이 내려다보여, 비선대까지 걷고도 체력이 남는 사람에게 맞아요.', null, null, '무료', '033-801-0900', '설악산 소공원 유료 주차장 이용', '비선대 이후 구간은 경사가 급하고 계단이 계속돼요.
코스마다 입산할 수 있는 시간이 달라 국립공원공단 누리집에서 미리 보세요.', null, 'open', null, null, '2026-11-21'),
  ('20000000-0000-4000-8000-000000000014', 'dalmabong-peak', '달마봉', '산', '소공원 동쪽의 바위 봉우리, 평소 출입 제한', '강원특별자치도 속초시 노학동 산1', 38.181947, 128.496060, '/places/dalmabong-peak.webp', '사진: 속초시 관광 누리집', 'https://www.sokcho.go.kr/ct/tour/attraction/nature?contentSeq=80', '파란 하늘 아래 바위로 솟은 달마봉', 'https://www.sokcho.go.kr/ct/tour/attraction/nature?contentSeq=80', 'https://map.naver.com/p/search/%EB%8B%AC%EB%A7%88%EB%B4%89', true, 'nature', '{}', '설악산 소공원 동쪽에 솟은 바위 봉우리예요. 자연 보호와 안전을 위해 평소에는 일반인 출입이 제한되는 구간이라, 트레킹 축제 같은 행사가 있을 때만 하루씩 임시로 열려요. 평소에는 소공원 일대에서 바라보는 풍경으로 즐기면 돼요.', null, '평소 일반인 출입 제한(행사 때만 임시 개방)', null, '033-801-0900', null, '출입 제한 구간에 들어가면 과태료를 낼 수 있어요.', null, 'open', '평소에는 일반인 출입이 제한돼 오를 수 없어요. 트레킹 축제 같은 행사 때만 하루씩 임시로 열려요.', null, '2026-11-21'),
  ('20000000-0000-4000-8000-000000000009', 'daepo-port', '대포항', '항구', '튀김골목과 수산시장이 있는 속초 남쪽 항구', '강원특별자치도 속초시 대포항1길 6-13', 38.173795, 128.606991, '/places/daepo-port.webp', '사진: 속초시 관광 누리집', 'https://www.sokcho.go.kr/ct/tour/attraction/experience?contentSeq=104', '대포항의 보행교와 정박한 배들', 'https://www.sokcho.go.kr/ct/tour/attraction/experience?contentSeq=104', 'https://map.naver.com/p/search/%EB%8C%80%ED%8F%AC%ED%95%AD', true, 'nature', '{}', '속초 남쪽 바닷가의 어항으로, 회와 해산물을 파는 대포항관광수산시장과 새우·오징어 같은 해산물을 튀겨 파는 튀김골목이 항구에 붙어 있어요. 항구를 한 바퀴 둘러보고 시장에서 먹거리를 사 먹으면 1시간 안팎이 걸려요. 북쪽의 외옹치항과 가까워 바닷가 산책과 묶어 들르기에 맞아요.', '항구는 늘 열려 있고, 시장 점포는 대체로 10:00~23:00(점포마다 다름)', null, '입장 무료(회·튀김은 점포별 가격)', null, '근처 공영주차장 이용', '점포마다 영업시간과 가격이 달라 주문 전에 확인하세요.', null, 'open', null, null, '2026-11-21'),
  ('20000000-0000-4000-8000-000000000021', 'sokcho-attraction-021', '대포항 전망대', '전망', '속초시의 산과 바다 풍경을 넓게 조망할 수 있는 대포항 전망대입니다.', '강원특별자치도 속초시 일원', 38.160763, 128.439790, null, null, null, null, 'https://www.sokcho.go.kr/ct/tour/attraction/nature?contentSeq=61', 'https://map.naver.com/p/search/%EB%8C%80%ED%8F%AC%ED%95%AD%20%EC%A0%84%EB%A7%9D%EB%8C%80', true, null, '{}', null, null, null, null, null, null, null, null, 'open', null, null, null),
  ('20000000-0000-4000-8000-000000000032', 'dongmyeong-port', '동명항', '항구', '영금정 옆 활어회센터가 있는 항구', '강원특별자치도 속초시 영금정로 50', 38.210568, 128.601462, '/places/dongmyeong-port.webp', '사진: 속초시 관광 누리집', 'https://www.sokcho.go.kr/ct/tour/attraction/experience?contentSeq=103', '바다 쪽에서 본 동명항 방파제와 등대 언덕', 'https://www.sokcho.go.kr/ct/tour/attraction/experience?contentSeq=103', 'https://map.naver.com/p/search/%EB%8F%99%EB%AA%85%ED%95%AD', true, 'nature', '{}', '속초 동북쪽 바닷가의 항구로, 방파제 입구의 동명활어센터에서는 1층 수조에서 횟감을 고르고 2층 식당에서 먹을 수 있어요. 영금정 해돋이 정자와 속초등대가 걸어서 닿는 거리라 해돋이나 바닷가 산책과 묶어 1~2시간 잡으면 좋아요.', '항구는 늘 열려 있고, 동명활어센터는 대체로 07:00~21:00', null, '입장 무료(회는 시가)', null, null, '회는 시가라 고르기 전에 가격을 물어보세요.', null, 'open', null, null, '2026-11-21'),
  ('20000000-0000-4000-8000-000000000029', 'balhae-history-hall', '발해역사관', '박물관', '발해의 역사와 문화를 전시하는 속초시립박물관의 별관', '강원특별자치도 속초시 신흥2길 16', 38.200842, 128.537251, '/places/balhae-history-hall.webp', '사진: 속초시 관광 누리집', 'https://www.sokcho.go.kr/ct/tour/attraction/experience?contentSeq=112', '돌벽과 유리창으로 된 발해역사관 건물 외관', 'https://www.sokcho.go.kr/ct/tour/attraction/experience?contentSeq=112', 'https://map.naver.com/p/search/%EB%B0%9C%ED%95%B4%EC%97%AD%EC%82%AC%EA%B4%80', true, 'exhibition', array['indoor', 'kids'], '속초시립박물관 부지 안에 있는 전시관으로, 발해의 역사와 유물·고분 자료를 전시해요. 발해 옷을 입어 보고 문양을 찍어 보는 체험실이 있어 초등학생과 함께 보기에 맞아요. 박물관 입장권으로 함께 볼 수 있고 실내라 날씨 영향이 없으며 30분 안팎이면 둘러봐요.', '3~10월 09:00~18:00, 11~2월 09:00~17:00(종료 1시간 전 매표 마감)', '매주 월요일, 1월 1일', '속초시립박물관 입장료에 포함(일반 2,000원 · 청소년·군인 1,500원 · 어린이 700원)', '033-639-2977', '무료(속초시립박물관 주차장)', '따로 입장권을 팔지 않고 속초시립박물관 입장권으로 함께 관람해요.
관람 종료 1시간 전에 매표를 마감해요.', null, 'open', null, null, '2026-11-21'),
  ('20000000-0000-4000-8000-000000000046', 'beombawi-rock', '범바위', '자연', '영랑호와 설악산·동해가 내려다보이는 바위 전망지', '강원특별자치도 속초시 금호동 610-22', 38.214716, 128.575824, '/places/beombawi-rock.webp', '사진: 속초시 관광 누리집', 'https://www.sokcho.go.kr/ct/tour/attraction/nature?contentSeq=140', '푸른 하늘 아래 둥글게 포개진 범바위의 큰 바위들', 'https://korean.visitkorea.or.kr/detail/ms_detail.do?cotid=899855c5-8cc4-4ec1-89d8-36bd2166016e', 'https://map.naver.com/p/search/%EB%B2%94%EB%B0%94%EC%9C%84', true, 'nature', array['free'], '영랑호 서남쪽 호숫가에 크고 작은 바위가 모여 있는 곳으로, 웅크린 범을 닮았다고 해서 이 이름이 붙었고 속초 8경에 들어가요. 입구에서 5분쯤 걸어 오르면 영랑호와 동해, 울산바위를 비롯한 설악산 능선이 한눈에 보여요. 영랑호 둘레길을 걷다가 잠깐 들르기 좋아요.', null, null, '무료', null, null, '오르는 길이 짧지만 가파른 바위라 미끄러워요.
비가 온 뒤나 얼음이 언 날에는 바위 위에 오르지 않는 편이 안전해요.', null, 'open', null, null, '2026-11-21'),
  ('20000000-0000-4000-8000-000000000042', 'bogwangsa-temple', '보광사', '사찰', '영랑호 호숫가의 작은 사찰', '강원특별자치도 속초시 영랑호반길 69-2', 38.213601, 128.585688, '/places/bogwangsa-temple.webp', '사진: 속초시 관광 누리집', 'https://www.sokcho.go.kr/ct/tour/attraction/culture?contentSeq=36', '잔디 마당 뒤로 선 보광사 법당', 'https://www.sokcho.go.kr/ct/tour/attraction/culture?contentSeq=36', 'https://map.naver.com/p/search/%EB%B3%B4%EA%B4%91%EC%82%AC', true, 'nature', array['free'], '영랑호 호숫가에 있는 절로, 목조 지장보살상과 옥으로 만든 와불상(누운 불상)을 모시고 있어요. 영랑호 산책길에 들러 30분 정도 조용히 둘러보기에 알맞아요.', null, null, '무료', '033-632-9800', null, '예불이나 법회 중에는 법당 안 촬영과 큰 소리를 삼가 주세요.', null, 'open', null, null, '2026-11-21'),
  ('20000000-0000-4000-8000-000000000015', 'biryong-falls', '비룡폭포', '폭포', '소공원에서 2.4km 걸어가는 높이 16m 계곡 폭포', '강원특별자치도 속초시 설악동 설악산국립공원', 38.161976, 128.501649, '/places/biryong-falls.webp', '사진: 속초시 관광 누리집', 'https://www.sokcho.go.kr/ct/tour/attraction/nature?contentSeq=79', '단풍 든 바위 절벽 사이로 떨어지는 비룡폭포', 'https://www.sokcho.go.kr/ct/tour/attraction/nature?contentSeq=79', 'https://map.naver.com/p/search/%EB%B9%84%EB%A3%A1%ED%8F%AD%ED%8F%AC', true, 'nature', array['free'], '토왕골 계곡 안쪽에 있는 높이 약 16m의 폭포로, 폭포 아래 맑은 소를 둘러 전망 데크가 놓여 있어요. 소공원 매표소에서 육담폭포를 지나 약 2.4km, 편도 1시간 안팎이 걸리며 난이도는 보통이에요. 여유가 있으면 약 400m 위 토왕성폭포 전망대까지 이어서 걸을 수 있어요.', '입산 가능 시간 동절기 04:00~12:00 · 하절기 03:00~14:00', null, '무료', '033-801-0900', '설악산 소공원 유료 주차장 이용', '폭포에서 토왕성폭포 쪽으로 곧장 가는 길은 낙석 위험으로 막혀 있어요.', null, 'open', null, null, '2026-11-21'),
  ('20000000-0000-4000-8000-000000000031', 'seokbong-ceramic-museum', '석봉도자기미술관', '미술관', '도자기 작품을 보고 물레 체험도 하는 무료 미술관', '강원특별자치도 속초시 엑스포로 156', 38.197882, 128.582597, '/places/seokbong-ceramic-museum.webp', '사진: 속초시 관광 누리집', 'https://www.sokcho.go.kr/ct/tour/attraction/experience?contentSeq=106', '백자와 청자가 진열장에 놓인 석봉도자기미술관 내부', 'http://www.dogong.net/', 'https://map.naver.com/p/search/%EC%84%9D%EB%B4%89%EB%8F%84%EC%9E%90%EA%B8%B0%EB%AF%B8%EC%88%A0%EA%B4%80', true, 'exhibition', array['indoor', 'kids', 'free'], '도예가 석봉 조무호의 작품과 도자기 벽화를 주제별 전시관 8곳에서 보여 주는 사립 미술관이에요. 개인 관람은 무료이고, 물레 성형·코일링·초벌 페인팅·머그컵 전사 같은 체험은 유료로 운영해요. 엑스포공원 근처 실내 시설이라 날씨와 상관없이 들를 수 있고, 관람만 하면 30분~1시간 정도면 충분해요.', '10:00~18:00', '매주 월요일(7월 중순~8월 중순은 휴무 없음)', '개인 무료 · 단체(10인 이상) 1인 3,000원 · 도자기 체험 20,000~50,000원', '033-638-7711', '미술관 앞 무료 공영주차장 이용', '도자기 체험은 안내데스크에서 신청하며 당일 현장 접수도 할 수 있어요.
물레·코일링·초벌 페인팅 작품은 가마에 구운 뒤 30~45일 후 택배로 받고, 택배비는 따로 내요.
외부 음식은 가지고 들어갈 수 없어요.', null, 'open', null, null, '2026-11-21'),
  ('20000000-0000-4000-8000-000000000010', 'seoraksan-sogongwon', '설악산 소공원', '자연', '케이블카·신흥사·주요 탐방로가 모이는 외설악 입구', '강원특별자치도 속초시 설악산로 1091', 38.172527, 128.493664, '/places/seoraksan-sogongwon.webp', '사진: 속초시 관광 누리집', 'https://www.sokcho.go.kr/ct/tour/attraction/nature?contentSeq=74', '하늘에서 본 단풍철 설악산 소공원', 'https://www.sokcho.go.kr/ct/tour/attraction/nature?contentSeq=74', 'https://map.naver.com/p/search/%EC%84%A4%EC%95%85%EC%82%B0%20%EC%86%8C%EA%B3%B5%EC%9B%90', true, 'nature', array['free', 'kids'], '설악동 안쪽 끝에 있는 외설악 탐방의 출발점으로, 설악케이블카 탑승장과 신흥사, 비룡폭포·비선대·울산바위로 가는 탐방로 입구가 모두 이곳에 모여 있어요. 산에 오르지 않아도 통일대불이 있는 신흥사 경내와 광장 주변을 걸어서 둘러볼 수 있고, 휴게소와 식당도 있어요. 속초 시내에서 시내버스가 닿아 차 없이도 오갈 수 있고, 단풍철에는 설악동 일대에 차가 몰려요.', null, null, '무료', '033-801-0900', '유료(차종·성수기에 따라 요금이 다름)', '단풍철에는 설악동 일대에 교통 통제와 셔틀버스 운영이 있을 수 있어요.', null, 'open', null, null, '2026-11-21'),
  ('20000000-0000-4000-8000-000000000017', 'seoraksan-native-botanical-garden', '설악산자생식물원', '식물원', '설악산 자생식물을 모아 둔 무료 생태 식물원', '강원특별자치도 속초시 바람꽃마을길 164', 38.196435, 128.524975, '/places/seoraksan-native-botanical-garden.webp', '사진: 속초시 관광 누리집', 'https://www.sokcho.go.kr/ct/tour/attraction/nature?contentSeq=77', '징검다리가 놓인 설악산자생식물원 연못', 'https://www.sokcho.go.kr/ct/tour/attraction/nature?contentSeq=77', 'https://map.naver.com/p/search/%EC%84%A4%EC%95%85%EC%82%B0%EC%9E%90%EC%83%9D%EC%8B%9D%EB%AC%BC%EC%9B%90', true, 'nature', array['free', 'kids'], '설악산에 자라는 희귀식물과 야생화를 모아 둔 속초시 생태학습장으로, 수생식물원·암석원·온실과 숲속 산책로, 아이들이 뛰어놀 수 있는 미로원이 있어요. 노학동 바람꽃마을 안쪽에 있어 설악동을 오가는 길에 들를 수 있고, 1시간 정도면 천천히 둘러볼 수 있어요.', '09:00~17:30', '연중무휴', '무료', '033-639-2928', '무료(소형차 약 20대)', '반려동물은 함께 들어갈 수 없어요.', null, 'open', null, null, '2026-11-21'),
  ('20000000-0000-4000-8000-000000000020', 'seorak-waterpia', '설악워터피아', '체험', '온천수로 운영하는 한화리조트 설악의 워터파크', '강원특별자치도 속초시 미시령로2983번길 111', 38.207519, 128.528968, '/places/seorak-waterpia.webp', '사진: 속초시 관광 누리집', 'https://www.sokcho.go.kr/ct/tour/attraction/experience?contentSeq=116', '야자수로 꾸민 설악워터피아 실내 파도풀', 'https://www.hanwharesort.co.kr/irsweb/resort3/tpark/tp_intro.do?tp_cd=0100', 'https://map.naver.com/p/search/%EC%84%A4%EC%95%85%EC%9B%8C%ED%84%B0%ED%94%BC%EC%95%84', true, 'water', array['indoor', 'kids'], '한화리조트 설악 안에 있는 워터파크로, 실내 파도풀·유수풀과 야외 스파 시설을 함께 운영해요. 겨울철에도 실내 시설과 스파밸리를 이용할 수 있어 아이와 함께 반나절 이상 보내기에 맞아요. 실외 놀이시설과 노천탕은 강풍·폭우·낙뢰 때 운영이 제한될 수 있어요.', '시즌별로 다름. 2026.10.12~2027.3.1은 주간권 10:00~17:00(입장 마감 16:30), Night Spa 18:00~20:30(입장 마감 20:00)', '연중무휴', '주간권 정상요금 대인 57,000원 · 소인 49,000원(2026.10.12~12.10 기준, 12.11~2027.3.1은 62,000원 · 53,000원)', '033-630-5800', '무료', '요금과 운영시간이 시즌마다 달라지므로 방문 날짜의 시즌을 공식 홈페이지에서 확인해야 해요.
2026.10.12~2027.3.1에는 실외 파도풀·토렌트리버 등 일부 실외 시설을 운영하지 않아요.
36개월 미만 유아는 방수 기저귀를 착용해야 하고, 놀이기구는 키와 나이 제한이 있어요.
돗자리·유모차 반입과 반려동물 동반 입장은 할 수 없어요.', null, 'open', null, null, '2026-11-21'),
  ('20000000-0000-4000-8000-000000000044', 'seorak-sunrise-park', '설악해맞이공원', '공원', '설악항 옆 바닷가의 조각 공원', '강원특별자치도 속초시 동해대로 3664', 38.163224, 128.608637, '/places/seorak-sunrise-park.webp', '사진: 속초시 관광 누리집', 'https://www.sokcho.go.kr/ct/tour/attraction/nature?contentSeq=135', '바다를 내려다보는 설악해맞이공원의 조형물과 잔디밭', 'https://korean.visitkorea.or.kr/detail/ms_detail.do?cotid=cb5d1e65-148e-44fd-99e8-6fc06d29a29a', 'https://map.naver.com/p/search/%EC%84%A4%EC%95%85%ED%95%B4%EB%A7%9E%EC%9D%B4%EA%B3%B5%EC%9B%90', true, 'nature', array['free'], '설악항 바로 옆 바닷가에 조각 작품을 세워 둔 공원으로, 테마 산책길을 따라 동해를 보며 걸을 수 있고 바닷가 쪽에 인어 연인 조각상이 있어요. 입장과 주차가 무료라 대포항이나 설악항에 가는 길에 30분쯤 쉬어 가기에 맞아요.', null, null, '무료', null, '무료', null, null, 'open', null, null, '2026-11-21'),
  ('20000000-0000-4000-8000-000000000043', 'sokcho-tourist-fish-market', '속초관광수산시장', '시장', '닭강정·건어물 가게가 모인 속초 대표 전통시장', '강원특별자치도 속초시 중앙로147번길 12', 38.203988, 128.590598, '/places/sokcho-tourist-fish-market.webp', '사진: 속초시 관광 누리집', 'https://www.sokcho.go.kr/ct/tour/attraction/nature?contentSeq=131', '지붕 덮인 골목에 가게가 늘어선 속초관광수산시장', 'https://www.sokcho-central.co.kr/', 'https://map.naver.com/p/search/%EC%86%8D%EC%B4%88%EA%B4%80%EA%B4%91%EC%88%98%EC%82%B0%EC%8B%9C%EC%9E%A5', true, 'nature', '{}', '옛 중앙시장으로, 상가 건물과 닭전골목·순대골목·젓갈골목 같은 품목별 골목으로 이루어진 전통시장이에요. 닭강정, 오징어순대, 건어물, 젓갈을 사고 지하 회센터에서 활어회를 먹을 수 있어요. 골목에 비가림 지붕이 있어 비 오는 날 들르기에도 무난하고, 아바이마을 갯배 선착장과 가까워요.', '대체로 08:00~24:00(점포마다 다름)', '점포마다 다름(지하 회센터는 매월 둘째 수요일 휴무, 8~9월은 무휴)', '입장 무료(상품은 점포별 가격)', null, '시장 주차장 약 350대, 08:00~21:00 유료(그 밖의 시간 무료), 물건을 사면 주차권 지급', '주차권은 하루 1시간까지 쓸 수 있고, 잃어버리면 하루 최대 요금을 내요.', null, 'open', null, null, '2026-11-21'),
  ('20000000-0000-4000-8000-000000000045', 'sokcho-lighthouse-observatory', '속초등대전망대', '전망', '영금정 옆 언덕에서 속초 앞바다를 내려다보는 무료 등대 전망대', '강원특별자치도 속초시 영금정로5길 8-28', 38.213639, 128.600278, '/places/sokcho-lighthouse-observatory.webp', '사진: Christophe95, CC BY-SA 4.0 (위키미디어 공용) · 원본에서 잘라냄', 'https://commons.wikimedia.org/wiki/File:Sokcho_from_the_Lighthouse_Observatory_1.jpg', '속초등대전망대에서 내려다본 동명항과 속초 시내', 'https://korean.visitkorea.or.kr/detail/ms_detail.do?cotid=e5eefdfb-cbc8-4a23-b0e8-d6fdc0fb97b0', 'https://map.naver.com/p/search/%EC%86%8D%EC%B4%88%EB%93%B1%EB%8C%80%EC%A0%84%EB%A7%9D%EB%8C%80', true, 'view', array['free'], '영금정 옆 언덕 위에 있는 속초등대의 전망대로, 속초항과 동해, 설악산 쪽을 함께 내려다볼 수 있어요. 입장료가 없고 영금정·동명항과 가까워 산책길에 30분쯤 들르기에 맞아요. 야외 구간이 많아 맑은 날에 가는 편이 좋아요.', '전망대 09:00~17:00, 야외 공간 09:00~18:00', '연중무휴', '무료', '033-633-3406', null, '실내 전망대는 야외 공간보다 한 시간 이른 17:00에 닫아요.
언덕 위에 있어 계단을 걸어 올라가야 하고, 바람이 강한 날에는 야외 전망이 불편할 수 있어요.', null, 'open', null, null, '2026-11-21'),
  ('20000000-0000-4000-8000-000000000048', 'sokcho-attraction-048', '속초문화예술회관', '문화시설', '속초시의 문화시설 매력을 직접 살펴볼 수 있는 여행 명소 속초문화예술회관입니다.', '강원특별자치도 속초시 번영로 155', 38.212903, 128.588796, null, null, null, null, 'https://www.sokcho.go.kr/ct/culture', 'https://map.naver.com/p/search/%EC%86%8D%EC%B4%88%EB%AC%B8%ED%99%94%EC%98%88%EC%88%A0%ED%9A%8C%EA%B4%80', true, null, '{}', null, null, null, null, null, null, null, null, 'open', null, null, null),
  ('20000000-0000-4000-8000-000000000004', 'sokcho-museum', '속초시립박물관', '박물관', '속초의 역사와 실향민 문화를 보여 주는 시립 박물관', '강원특별자치도 속초시 신흥2길 16', 38.200540, 128.539536, '/places/sokcho-museum.webp', '사진: 속초시 관광 누리집', 'https://www.sokcho.go.kr/ct/tour/attraction/experience?contentSeq=111', '하늘에서 본 속초시립박물관 실향민문화촌의 기와집과 마당', 'https://www.sokcho.go.kr/ct/tour/attraction/experience?contentSeq=111', 'https://map.naver.com/p/search/%EC%86%8D%EC%B4%88%EC%8B%9C%EB%A6%BD%EB%B0%95%EB%AC%BC%EA%B4%80', true, 'exhibition', array['indoor', 'kids'], '속초의 선사 유적과 어촌·실향민 문화를 전시하는 시립 박물관이에요. 야외에는 실향민문화촌이, 옆에는 발해역사관이 있어 한 번 입장해 함께 둘러볼 수 있고 어린이 민속체험실도 있어요. 전시실은 실내지만 문화촌은 야외라 날씨가 좋은 날에 1~2시간 잡고 보기에 맞아요.', '3~10월 09:00~18:00(입장 마감 17:00), 11~2월 09:00~17:00(입장 마감 16:00)', '매주 월요일, 1월 1일', '일반 2,000원 · 청소년·군인 1,500원 · 어린이 700원(개인 기준)', '033-639-2977', '무료', '관람 종료 1시간 전에 입장을 마감해요.
입장권 하나로 발해역사관과 실향민문화촌까지 함께 볼 수 있어요.', null, 'open', null, null, '2026-11-21'),
  ('20000000-0000-4000-8000-000000000033', 'sokcho-port', '속초항', '항구', '오징어난전과 제철 먹거리 장터가 서는 도심 항구', '강원특별자치도 속초시 동명동 일대', 38.208676, 128.595108, '/places/sokcho-port.webp', '사진: 속초시 관광 누리집', 'https://www.sokcho.go.kr/ct/tour/attraction/experience?contentSeq=101', '크루즈가 정박한 속초항과 여객터미널', 'https://www.sokcho.go.kr/ct/tour/attraction/experience?contentSeq=101', 'https://map.naver.com/p/search/%EC%86%8D%EC%B4%88%ED%95%AD', true, 'nature', array['free'], '속초 도심 동쪽의 항구로, 동명항과 이어진 부두에서 고깃배와 바다를 볼 수 있어요. 5월 중순부터 12월까지는 부두의 오징어난전에서 그날 잡은 오징어회를 시가로 팔고, 11~12월에는 도루묵·양미리 구이 장터가 열려 제철 먹거리를 맛보러 가기 좋아요.', '오징어난전은 5월 중순~12월, 대체로 06:00~20:00(물량이 떨어지면 마감)', null, '입장 무료(난전 음식은 시가)', null, null, null, null, 'open', null, null, '2026-11-21'),
  ('20000000-0000-4000-8000-000000000001', 'sokcho-beach', '속초해수욕장', '해변', '터미널에서 걸어가는 속초 도심의 대표 해변', '강원특별자치도 속초시 해오름로 190', 38.190798, 128.603467, '/places/sokcho-beach.webp', '사진: 속초시 관광 누리집', 'https://www.sokcho.go.kr/ct/tour/attraction/nature?contentSeq=87', '이정표와 SOKCHO 글자가 있는 속초해수욕장 백사장', 'https://www.sokcho.go.kr/ct/tour/attraction/nature?contentSeq=87', 'https://map.naver.com/p/search/%EC%86%8D%EC%B4%88%ED%95%B4%EC%88%98%EC%9A%95%EC%9E%A5', true, 'nature', array['free', 'kids'], '고속버스터미널에서 걸어갈 수 있을 만큼 도심과 가까운 속초의 대표 해변이에요. 물이 맑고 경사가 완만하며, 모래사장에 사진 찍기 좋은 조형물이 있고 뒤쪽 솔숲에는 산책로가 있어요.', '물놀이는 여름 개장 기간(7월 초~8월 하순)에만 가능', null, '무료', null, '무료', '개장 기간이 아니면 안전요원이 없어 물에 들어가지 마세요.
